'use client';
import { useEffect, useState } from 'react';
import { File } from "@lib/code-engine/react/File";
import { cn } from "@lib/utils";
import { resolveCodeBlockMessages } from './code-block-messages';
import { getCodeBlockStyle } from './code-block-theme';
import { CodeBlockToolbar } from './code-block-toolbar';
import type { CodeBlockProps } from './code-block-types';
export function CodeBlock<LAnnotation = undefined, Caret = undefined>({ appearance = 'zeron', themeMode = 'inherit', toolbar = true, messages, onCopy, onCopyError, onOverflowChange, className, style, file, options, renderCustomHeader, ...props }: CodeBlockProps<LAnnotation, Caret>): React.JSX.Element {
    const [overflow, setOverflow] = useState<'scroll' | 'wrap'>(options?.overflow ?? 'scroll');
    useEffect(() => {
        setOverflow(options?.overflow ?? 'scroll');
    }, [options?.overflow]);
    const resolvedMessages = resolveCodeBlockMessages(messages);
    const toolbarRenderer = renderCustomHeader ??
        (toolbar
            ? () => (<CodeBlockToolbar filename={file.name} contents={file.contents} overflow={overflow} messages={resolvedMessages} onCopy={onCopy} onCopyError={onCopyError} onOverflowChange={(nextOverflow) => {
                    setOverflow(nextOverflow);
                    onOverflowChange?.(nextOverflow);
                }}/>)
            : undefined);
    return (<File {...props} file={file} options={{ ...options, overflow }} renderCustomHeader={toolbarRenderer} className={cn(appearance === 'zeron' && 'zeron-code-block', 'block overflow-hidden rounded-xl border border-border bg-surface-floating', className)} style={getCodeBlockStyle(themeMode, style)}/>);
}

